import React, { useState } from "react";
import MonitoringWidget from "../components/MonitoringWidget";
import MLWidget from "../components/MLWidget";
import AutomationControl from "../components/AutomationControl";
import { Button, Switch, Typography } from "@mui/material";

const AdminDashboard = () => {
  // State for dark mode toggle
  const [darkMode, setDarkMode] = useState(false);

  // Dummy data for server logs and error rates
  const serverLogs = [
    { time: "10:15 AM", message: "Server started successfully." },
    { time: "10:20 AM", message: "Database connection established." },
    { time: "10:25 AM", message: "Cache cleared." },
  ];

  const errorRates = [
    { service: "API Gateway", rate: "1.2%" },
    { service: "Database", rate: "0.5%" },
    { service: "Web Server", rate: "0.8%" },
  ];

  // Toggle dark mode
  const handleDarkModeToggle = () => {
    setDarkMode((prev) => !prev);
  };

  return (
    <div
      style={{
        padding: "2rem",
        backgroundColor: darkMode ? "#1a1a1a" : "#f5f5f5",
        color: darkMode ? "#ffffff" : "#000000",
        minHeight: "100vh",
      }}
    >
      {/* Header Section */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "2rem",
        }}
      >
        <Typography variant="h4" component="h1">
          Admin Dashboard
        </Typography>
        <div style={{ display: "flex", alignItems: "center", gap: "1rem" }}>
          <Typography>Dark Mode</Typography>
          <Switch checked={darkMode} onChange={handleDarkModeToggle} />
        </div>
      </div>

      {/* Dashboard Widgets */}
      <div style={{ display: "flex", gap: "2rem", flexWrap: "wrap" }}>
        <MonitoringWidget />
        <MLWidget title="Model Accuracy" value="92%" />
      </div>

      {/* Server Logs Section */}
      <div style={{ marginTop: "3rem" }}>
        <Typography variant="h5" component="h2" gutterBottom>
          Server Logs
        </Typography>
        <div
          style={{
            backgroundColor: darkMode ? "#333333" : "#ffffff",
            borderRadius: "8px",
            padding: "1rem",
            boxShadow: "0px 4px 6px rgba(0, 0, 0, 0.1)",
          }}
        >
          {serverLogs.map((log, index) => (
            <div
              key={index}
              style={{
                display: "flex",
                justifyContent: "space-between",
                marginBottom: "0.5rem",
              }}
            >
              <Typography>{log.time}</Typography>
              <Typography>{log.message}</Typography>
            </div>
          ))}
        </div>
      </div>

      {/* Error Rates Section */}
      <div style={{ marginTop: "3rem" }}>
        <Typography variant="h5" component="h2" gutterBottom>
          Error Rates
        </Typography>
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))",
            gap: "1rem",
          }}
        >
          {errorRates.map((error, index) => (
            <div
              key={index}
              style={{
                backgroundColor: darkMode ? "#333333" : "#ffffff",
                borderRadius: "8px",
                padding: "1rem",
                boxShadow: "0px 4px 6px rgba(0, 0, 0, 0.1)",
              }}
            >
              <Typography variant="subtitle1" gutterBottom>
                {error.service}
              </Typography>
              <Typography variant="h6" color="primary">
                {error.rate}
              </Typography>
            </div>
          ))}
        </div>
      </div>

      {/* Automation Controls Section */}
      <div style={{ marginTop: "3rem" }}>
        <Typography variant="h5" component="h2" gutterBottom>
          Automation Controls
        </Typography>
        <AutomationControl />
      </div>
    </div>
  );
};

export default AdminDashboard;
